CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users(id text PRIMARY KEY, username text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '');
CREATE TABLE memberships(project_id text REFERENCES projects(id), user_id text REFERENCES users(id), role text NOT NULL CHECK(role IN ('admin','reviewer','member','reader')), PRIMARY KEY(project_id,user_id));
CREATE TABLE auth_tokens(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, kind text NOT NULL CHECK(kind IN ('cookie','api')), name text NOT NULL DEFAULT '', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id), owner_id text NOT NULL REFERENCES users(id), visibility text NOT NULL CHECK(visibility IN ('team','private')), title text NOT NULL, source text NOT NULL, raw_text text NOT NULL, raw_hash text NOT NULL, events jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, owner_id, visibility, raw_hash));
CREATE TABLE extraction_runs(id text PRIMARY KEY, session_id text NOT NULL REFERENCES sessions(id), provider text NOT NULL, status text NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE candidates(id text PRIMARY KEY, session_id text NOT NULL REFERENCES sessions(id), topic_key text NOT NULL, title text NOT NULL, body text NOT NULL, kind text NOT NULL, rationale text NOT NULL DEFAULT '', rejected_alternatives text NOT NULL DEFAULT '', revisit_condition text NOT NULL DEFAULT '', evidence jsonb NOT NULL, confidence real NOT NULL CHECK(confidence BETWEEN 0 AND 1), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), review_note text, reviewed_by text REFERENCES users(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,topic_key));
CREATE TABLE knowledge(id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id), owner_id text NOT NULL REFERENCES users(id), visibility text NOT NULL CHECK(visibility IN ('team','private')), topic_key text NOT NULL, title text NOT NULL, body text NOT NULL, kind text NOT NULL, rationale text NOT NULL DEFAULT '', rejected_alternatives text NOT NULL DEFAULT '', revisit_condition text NOT NULL DEFAULT '', source_session_id text NOT NULL REFERENCES sessions(id), candidate_id text REFERENCES candidates(id), evidence jsonb NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','superseded','expired')), superseded_by text REFERENCES knowledge(id), expires_at timestamptz, search_text tsvector NOT NULL, embedding vector(256) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX knowledge_active_topic ON knowledge(project_id,topic_key,(CASE WHEN visibility='private' THEN owner_id ELSE 'team' END)) WHERE status='active';
CREATE INDEX knowledge_fts ON knowledge USING gin(search_text);
CREATE INDEX knowledge_scope ON knowledge(project_id,visibility,owner_id,status);
CREATE TABLE knowledge_versions(id text PRIMARY KEY, knowledge_id text NOT NULL REFERENCES knowledge(id), version integer NOT NULL, snapshot jsonb NOT NULL, actor_id text NOT NULL REFERENCES users(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(knowledge_id,version));
CREATE TABLE conflicts(id text PRIMARY KEY, candidate_id text NOT NULL REFERENCES candidates(id), knowledge_id text NOT NULL REFERENCES knowledge(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), resolved_by text REFERENCES users(id), resolution text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_id,knowledge_id));
CREATE TABLE recall_logs(id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id), actor_id text NOT NULL REFERENCES users(id), query text NOT NULL, channel text NOT NULL, results jsonb NOT NULL, duration_ms integer NOT NULL, feedback integer CHECK(feedback IN (-1,1)), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id), actor_id text NOT NULL REFERENCES users(id), action text NOT NULL, entity_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable evidence or version'; END; $$;
CREATE TRIGGER immutable_sessions BEFORE UPDATE OR DELETE ON sessions FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_versions BEFORE UPDATE OR DELETE ON knowledge_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
